<?php namespace App\Filament\Resources\StudentMeritActionResource\Pages;use App\Filament\Resources\StudentMeritActionResource;use App\Services\PeriodGuard;use Filament\Resources\Pages\CreateRecord;class CreateStudentMeritAction extends CreateRecord{protected static string $resource=StudentMeritActionResource::class;protected function mutateFormDataBeforeCreate(array $d):array{$p=request()->attributes->get('academic_period');if($p){PeriodGuard::writable($p->id);$d['academic_period_id']=$p->id;}$d['created_by']=auth()->id();$d['status']='active';return $d;}}